//! End-to-end simulation tests on a real Verilator.
//!
//! Each test compiles a hand-written Verilog DUT fixture together with a
//! testbench generated by [`shyhdl::testbench`], runs it through
//! [`shyhdl::simulation`], and checks the externally observable result: the
//! classification, the protocol lines, the waveform scopes and the manifest.
//!
//! The DUTs are hand-written with independent formulations (a structural carry
//! chain compared against `a + b`, and a second reference `a + b` module), so the
//! checks do not merely re-run the implementation under test. Nothing here is a
//! frontend end-to-end test: the frontend milestone is not part of these files.
//!
//! A missing Verilator fails the test with a clear message (no result is faked
//! and no path is skipped).

use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use shyhdl::metadata::ValueType;
use shyhdl::simulation::{load_manifest, Outcome, SimOptions, Simulator, SourceFile, WaveOption};
use shyhdl::testbench::{compile_testbench, DesignInfo, ModulePort, PortDirection};

fn uint(width: u32) -> ValueType {
    ValueType::UInt { width }
}

fn bool_port(source: &str, direction: PortDirection) -> ModulePort {
    ModulePort::new(source, source, direction, ValueType::Bool)
}

fn dir(name: &str) -> PathBuf {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("target/sim-e2e")
        .join(name);
    std::fs::create_dir_all(&path).expect("create build directory");
    path
}

/// A relative build directory: `cargo test` runs integration tests with the
/// package root as the working directory, and a relative `--out` is what a CLI
/// user gets by default.
fn relative_dir(name: &str) -> PathBuf {
    let path = PathBuf::from("target").join("sim-e2e").join(name);
    std::fs::create_dir_all(&path).expect("create build directory");
    path
}

fn simulator() -> Simulator {
    Simulator::discover().unwrap_or_else(|error| {
        panic!(
            "a real Verilator is required for these tests and none was usable: {error}\n\
             source the tool environment (for example the kit's env.sh) before running cargo test"
        )
    })
}

/// The exhaustive adder fixture: a structural carry chain under test, a
/// behavioural `a + b` reference, and a comparator that exposes any difference.
const ADDER_DUT: &str = r#"
module Adder8(input [7:0] a, input [7:0] b, output [7:0] c, output cout);
  wire [7:0] p = a ^ b;
  wire [8:0] carry;
  assign carry[0] = 1'b0;
  assign carry[8:1] = (a & b) | (p & carry[7:0]);
  assign c = p ^ carry[7:0];
  assign cout = carry[8];
endmodule

module RefAdder8(input [7:0] a, input [7:0] b, output [7:0] c, output cout);
  assign {cout, c} = a + b;
endmodule

module AdderCompare(input [7:0] a, input [7:0] b, output mismatch, output [7:0] sum, output carry);
  wire [7:0] dut_c;
  wire [7:0] ref_c;
  wire dut_cout;
  wire ref_cout;
  Adder8 u_dut(.a(a), .b(b), .c(dut_c), .cout(dut_cout));
  RefAdder8 u_ref(.a(a), .b(b), .c(ref_c), .cout(ref_cout));
  assign mismatch = (dut_c !== ref_c) || (dut_cout !== ref_cout);
  assign sum = dut_c;
  assign carry = dut_cout;
endmodule
"#;

fn adder_design() -> DesignInfo {
    DesignInfo::new(
        "AdderCompare",
        "AdderCompare",
        vec![
            ModulePort::new("a", "a", PortDirection::In, uint(8)),
            ModulePort::new("b", "b", PortDirection::In, uint(8)),
            ModulePort::new("mismatch", "mismatch", PortDirection::Out, ValueType::Bool),
            ModulePort::new("sum", "sum", PortDirection::Out, uint(8)),
            ModulePort::new("carry", "carry", PortDirection::Out, ValueType::Bool),
        ],
    )
}

#[test]
fn adder8_is_exhaustive_and_matches_an_independent_reference() {
    // The spot checks are computed here, in Rust, and embedded into the
    // testbench, so those pairs are compared against a reference that is not the
    // DUT's own RTL.
    let pairs: [(u8, u8); 6] = [
        (0x00, 0x00),
        (0xff, 0xff),
        (0x80, 0x80),
        (0xff, 0x01),
        (0x7f, 0x7f),
        (0x01, 0xfe),
    ];
    let mut spot = String::new();
    for (a, b) in pairs {
        let sum = u16::from(a) + u16::from(b);
        spot.push_str(&format!(
            "        dut.a = 0x{a:02x}u8;\n        dut.b = 0x{b:02x}u8;\n        delay(ps(1));\n\
             \x20       assert_eq!(dut.sum, 0x{:02x}u8);\n        assert!(dut.carry == {});\n",
            (sum & 0xff) as u8,
            sum > 0xff
        ));
    }
    let source = format!(
        r##"
#[hardware_test]
fn adder8_exhaustive() {{
    let mut dut = AdderCompare::new();
    let mut count: uint<17> = 0;
    initial! {{
        dut.a = 0x00u8;
        dut.b = 0x00u8;
        delay(ps(1));
        assert!(dut.mismatch == false);
{spot}        for i in 0..256 {{
            for j in 0..256 {{
                dut.a = i[0..8];
                dut.b = j[0..8];
                delay(ps(1));
                count = count + 1;
                if (dut.mismatch == true) {{
                    assert!(dut.mismatch == false);
                }}
            }}
        }}
        assert_eq!(count, 0x10000);
        pass!();
        finish!();
    }}
}}
"##
    );
    let artifact = compile_testbench(&source, "adder8.shy", "adder8_exhaustive", &adder_design())
        .expect("generate the exhaustive testbench");
    // A relative build directory with non-ASCII characters: the default of a CLI
    // `--out build`, and the path shape that must not turn into `build/build/...`.
    let build_dir = relative_dir("加法器穷举/sim");
    let mut options = SimOptions::for_testbench(
        build_dir.clone(),
        &artifact,
        &adder_design(),
        vec![SourceFile::new("adder8_dut.v", ADDER_DUT)],
    );
    options.sampling = "all 65536 input pairs, one precision tick after each drive".into();
    let report = simulator()
        .run(&options)
        .expect("run the exhaustive simulation");

    assert!(
        report.is_pass(),
        "exhaustive adder run did not pass: {}\nstdout:\n{}\nstderr:\n{}",
        report.summary_line(),
        report.stdout,
        report.stderr
    );
    assert_eq!(report.fails, 0);
    assert_eq!(
        report.markers, 1,
        "the explicit case marker must have completed"
    );
    assert_eq!(report.passes, 2, "one marker plus the finishing PASS");
    assert!(
        report
            .stdout
            .contains("SHYHDL_PASS test=adder8_exhaustive case=finish"),
        "{}",
        report.stdout
    );
    // The testbench asserts count == 0x10000 itself; no failure means the loop
    // really covered every pair.
    assert_eq!(report.exit_code, Some(0));
}

/// Register with an asynchronous reset and an enable, plus a two-stage pipeline,
/// behind one top module so both acceptance cases run in a single build.
const REGPIPE_DUT: &str = r#"
module Reg8(input clk, input rst_n, input enable, input [7:0] d, output reg [7:0] q);
  always @(posedge clk or negedge rst_n)
    if (!rst_n) q <= 8'd0;
    else if (enable) q <= d;
endmodule

module Pipe2(input clk, input rst_n, input [7:0] d, output reg [7:0] q1, output reg [7:0] q2);
  always @(posedge clk or negedge rst_n)
    if (!rst_n) begin q1 <= 8'd0; q2 <= 8'd0; end
    else begin q1 <= d; q2 <= q1; end
endmodule

module RegPipeTop(
    input clk,
    input rst_n,
    input enable,
    input [7:0] rd,
    output [7:0] rq,
    input [7:0] pd,
    output [7:0] pq1,
    output [7:0] pq2
);
  Reg8 u_reg(.clk(clk), .rst_n(rst_n), .enable(enable), .d(rd), .q(rq));
  Pipe2 u_pipe(.clk(clk), .rst_n(rst_n), .d(pd), .q1(pq1), .q2(pq2));
endmodule
"#;

fn regpipe_design() -> DesignInfo {
    DesignInfo::new(
        "RegPipeTop",
        "RegPipeTop",
        vec![
            bool_port("clk", PortDirection::In),
            bool_port("rst_n", PortDirection::In),
            bool_port("enable", PortDirection::In),
            ModulePort::new("rd", "rd", PortDirection::In, uint(8)),
            ModulePort::new("rq", "rq", PortDirection::Out, uint(8)),
            ModulePort::new("pd", "pd", PortDirection::In, uint(8)),
            ModulePort::new("pq1", "pq1", PortDirection::Out, uint(8)),
            ModulePort::new("pq2", "pq2", PortDirection::Out, uint(8)),
        ],
    )
}

/// A test that walks the clock by explicit delays, so every check happens at a
/// known time and never on a `#0` "barrier".
const REGPIPE_TEST: &str = r##"
#[hardware_test]
fn reset_enable_pipeline() {
    let mut dut = RegPipeTop::new();
    clock!(dut.clk, period = ns(10), initial = false);
    reset!(dut.rst_n, active_low, setup = ns(12), hold = ns(24));
    initial! {
        dut.enable = true;
        dut.rd = 0xffu8;
        dut.pd = 0x00u8;
        wait(posedge(dut.clk));
        delay(ps(1));
        assert_eq!(dut.rq, 0xffu8);
        delay(ns(7));
        assert_eq!(dut.rq, 0x00u8);
        delay(ns(14));
        assert_eq!(dut.rq, 0x00u8);
        assert_eq!(dut.pq1, 0x00u8);
        pass!();
        delay(ns(10));
        dut.enable = true;
        dut.rd = 0x5au8;
        wait(posedge(dut.clk));
        delay(ps(1));
        assert_eq!(dut.rq, 0x5au8);
        pass!();
        dut.enable = false;
        dut.rd = 0x11u8;
        wait(posedge(dut.clk));
        delay(ps(1));
        assert_eq!(dut.rq, 0x5au8);
        pass!();
        dut.pd = 0x01u8;
        wait(posedge(dut.clk));
        delay(ps(1));
        assert_eq!(dut.pq1, 0x01u8);
        assert_eq!(dut.pq2, 0x00u8);
        dut.pd = 0x02u8;
        wait(posedge(dut.clk));
        delay(ps(1));
        assert_eq!(dut.pq1, 0x02u8);
        assert_eq!(dut.pq2, 0x01u8);
        pass!();
        finish!();
    }
}
"##;

#[test]
fn async_reset_enable_and_pipeline_semantics() {
    let artifact = compile_testbench(
        REGPIPE_TEST,
        "regpipe.shy",
        "reset_enable_pipeline",
        &regpipe_design(),
    )
    .expect("generate");
    let build_dir = dir("regpipe");
    let mut options = SimOptions::for_testbench(
        build_dir.clone(),
        &artifact,
        &regpipe_design(),
        vec![SourceFile::new("regpipe_dut.v", REGPIPE_DUT)],
    );
    options.wave = WaveOption::vcd();
    options.design_build_id = Some("fixture-build-id-1".to_string());
    let simulator = simulator();
    let report = simulator.run(&options).expect("run the simulation");

    assert!(
        report.is_pass(),
        "reset/enable/pipeline run did not pass: {}\n{}",
        report.summary_line(),
        report.fail_lines.join("\n")
    );
    assert_eq!(
        report.markers, 4,
        "four explicitly marked cases must have completed"
    );

    // A waveform was actually written and its scopes match the testbench
    // artifact, which is what replay pairs a recording with.
    let wave_path = report.wave_path.clone().expect("a waveform was requested");
    assert!(wave_path.is_file(), "{}", wave_path.display());
    assert_eq!(report.wave_timescale.as_deref(), Some("1ps"));
    let scopes = vcd_scopes(&wave_path);
    let expected_scope = &artifact.instances[0].scope;
    assert!(
        scopes.iter().any(|scope| scope == expected_scope),
        "waveform scopes {scopes:?} do not contain {expected_scope}"
    );

    // The manifest pairs run, design, waveform and scopes without recomputing
    // any id.
    let manifest = load_manifest(&report.manifest_path).expect("load manifest");
    assert_eq!(manifest.run_id, report.run_id);
    assert_eq!(manifest.outcome, "pass");
    assert_eq!(
        manifest.design.build_id.as_deref(),
        Some("fixture-build-id-1")
    );
    assert_eq!(manifest.design.top, "RegPipeTop");
    assert_eq!(manifest.test.name, "reset_enable_pipeline");
    assert_eq!(manifest.test.timeunit, "1ns");
    assert_eq!(manifest.test.timeprecision, "1ps");
    assert_eq!(manifest.test.top, artifact.top);
    assert_eq!(manifest.test.top_type, artifact.top_type);
    assert_eq!(
        manifest.paths.dut_verilog,
        vec!["regpipe_dut.v".to_string()]
    );
    assert_eq!(manifest.paths.tb_verilog, format!("{}.v", artifact.top));
    assert!(
        manifest.backend.version.contains("Verilator"),
        "{}",
        manifest.backend.version
    );
    assert_eq!(manifest.roots.len(), 1);
    assert_eq!(manifest.roots[0].wave_root, *expected_scope);
    assert_eq!(manifest.roots[0].source_root, "RegPipeTop");
    assert_eq!(manifest.roots[0].var, "dut");
    let wave = manifest.wave.expect("wave recorded in the manifest");
    assert_eq!(wave.path, "wave.vcd");
    assert_eq!(wave.format, "vcd");
    assert_eq!(wave.timescale_in_file.as_deref(), Some("1ps"));
    assert_eq!(manifest.counts.passes, report.passes);
    assert_eq!(manifest.counts.fails, report.fails);
}

#[test]
fn a_test_that_never_ends_is_a_timeout_and_leaves_no_orphans() {
    let source = r##"
#[hardware_test]
fn never_ends() {
    let mut dut = RegPipeTop::new();
    clock!(dut.clk, period = ns(10), initial = false);
    initial! {
        dut.enable = true;
        dut.rd = 0x01u8;
        wait_until(dut.rq == 0xffu8);
    }
}
"##;
    let artifact = compile_testbench(source, "regpipe.shy", "never_ends", &regpipe_design())
        .expect("generate");
    let build_dir = dir("timeout");
    let mut options = SimOptions::for_testbench(
        build_dir.clone(),
        &artifact,
        &regpipe_design(),
        vec![SourceFile::new("regpipe_dut.v", REGPIPE_DUT)],
    );
    options.timeout = Duration::from_secs(2);
    let report = simulator().run(&options).expect("run the simulation");

    assert_eq!(
        report.outcome,
        Outcome::Timeout,
        "{}",
        report.summary_line()
    );
    assert_eq!(
        report.passes, 0,
        "a test that never ends must not report a PASS"
    );
    assert!(report.fails == 0, "{}", report.fail_lines.join("\n"));

    // The deadline tool kills the whole process group: nothing of this build may
    // still be running.
    let needle = build_dir.display().to_string();
    let deadline = Instant::now() + Duration::from_secs(5);
    let mut leftover = process_ids_matching(&needle);
    while !leftover.is_empty() && Instant::now() < deadline {
        std::thread::sleep(Duration::from_millis(100));
        leftover = process_ids_matching(&needle);
    }
    assert!(
        leftover.is_empty(),
        "orphaned processes left behind: {leftover:?}"
    );

    let manifest = load_manifest(&report.manifest_path).expect("load manifest");
    assert_eq!(manifest.outcome, "timeout");
    assert_eq!(manifest.counts.passes, 0);
}

#[test]
fn manifest_validation_rejects_a_broken_recording() {
    let dir = dir("manifest");
    let path = dir.join("broken.manifest.json");
    std::fs::write(
        &path,
        r#"{"schema":3,"run_id":"","design":{"top":"t","top_source_name":"t","build_id":null},
            "test":{"name":"x","top":"tb","top_type":"Vtb","timeunit":"1ns","timeprecision":"1ps"},
            "paths":{"manifest":"run.manifest.json","dut_verilog":["dut.v"],"tb_verilog":"tb.v",
                     "metadata":null,"build_log":"build.log"},
            "wave":null,"roots":[],"clocks":[],
            "backend":{"name":"verilator","version":"v","flags":[]},
            "seed":null,"parameters":[],"sampling":"s","outcome":"pass","exit_code":0,
            "counts":{"passes":1,"fails":0,"markers":0,"expected_markers":null}}"#,
    )
    .unwrap();
    let error = load_manifest(&path).unwrap_err().to_string();
    assert!(error.contains("run_id"), "{error}");

    std::fs::write(
        &path,
        r#"{"schema":3,"run_id":"r","design":{"top":"t","top_source_name":"t","build_id":null},
            "test":{"name":"x","top":"tb","top_type":"Vtb","timeunit":"1ns","timeprecision":"1ps"},
            "paths":{"manifest":"run.manifest.json","dut_verilog":["/abs/dut.v"],"tb_verilog":"tb.v",
                     "metadata":null,"build_log":"build.log"},
            "wave":null,"roots":[],"clocks":[],
            "backend":{"name":"verilator","version":"v","flags":[]},
            "seed":null,"parameters":[],"sampling":"s","outcome":"pass","exit_code":0,
            "counts":{"passes":1,"fails":0,"markers":0,"expected_markers":null}}"#,
    )
    .unwrap();
    let error = load_manifest(&path).unwrap_err().to_string();
    assert!(error.contains("relative"), "{error}");

    // Two roots with the same `var` would make clock/root selection ambiguous.
    std::fs::write(
        &path,
        r#"{"schema":3,"run_id":"r","design":{"top":"t","top_source_name":"t","build_id":null},
            "test":{"name":"x","top":"tb","top_type":"Vtb","timeunit":"1ns","timeprecision":"1ps"},
            "paths":{"manifest":"run.manifest.json","dut_verilog":["dut.v"],"tb_verilog":"tb.v",
                     "metadata":null,"build_log":"build.log"},
            "wave":null,
            "roots":[{"source_root":"t","wave_root":"TOP.tb.u_a","var":"dut","instance":"u_a",
                      "module":"m","module_source_name":"m"},
                     {"source_root":"t","wave_root":"TOP.tb.u_b","var":"dut","instance":"u_b",
                      "module":"m","module_source_name":"m"}],
            "clocks":[],"backend":{"name":"verilator","version":"v","flags":[]},
            "seed":null,"parameters":[],"sampling":"s","outcome":"pass","exit_code":0,
            "counts":{"passes":1,"fails":0,"markers":0,"expected_markers":null}}"#,
    )
    .unwrap();
    let error = load_manifest(&path).unwrap_err().to_string();
    assert!(error.contains("repeated"), "{error}");

    // A genuine older recording: schema 2 has no `clocks`, and that must be
    // reported as a version problem instead of a missing field.
    std::fs::write(
        &path,
        r#"{"schema":2,"run_id":"r","design":{"top":"t","top_source_name":"t","build_id":"b"},
            "test":{"name":"x","top":"tb","top_type":"Vtb","timeunit":"1ns","timeprecision":"1ps"},
            "paths":{"manifest":"run.manifest.json","dut_verilog":["dut.v"],"tb_verilog":"tb.v",
                     "metadata":null,"build_log":"build.log"},
            "wave":{"path":"wave.vcd","format":"vcd","timescale_in_file":"1ps",
                    "digest":"fnv1a64-0123456789abcdef"},
            "roots":[{"source_root":"t","wave_root":"TOP.tb.u_dut","var":"dut","instance":"u_dut",
                      "module":"m","module_source_name":"m"}],
            "backend":{"name":"verilator","version":"v","flags":[]},
            "seed":null,"parameters":[],"sampling":"s","outcome":"pass","exit_code":0,
            "counts":{"passes":1,"fails":0,"markers":0,"expected_markers":null}}"#,
    )
    .unwrap();
    let error = load_manifest(&path).unwrap_err().to_string();
    assert!(error.contains("schema version 2"), "{error}");

    std::fs::write(
        &path,
        r#"{"schema":9,"run_id":"r","design":{"top":"t","top_source_name":"t","build_id":null},
            "test":{"name":"x","top":"tb","top_type":"Vtb","timeunit":"1ns","timeprecision":"1ps"},
            "paths":{"manifest":"run.manifest.json","dut_verilog":["dut.v"],"tb_verilog":"tb.v",
                     "metadata":null,"build_log":"build.log"},
            "wave":null,"roots":[],"clocks":[],
            "backend":{"name":"verilator","version":"v","flags":[]},
            "seed":null,"parameters":[],"sampling":"s","outcome":"pass","exit_code":0,
            "counts":{"passes":1,"fails":0,"markers":0,"expected_markers":null}}"#,
    )
    .unwrap();
    let error = load_manifest(&path).unwrap_err().to_string();
    assert!(error.contains("schema version"), "{error}");
}

#[test]
fn a_space_in_the_build_directory_is_reported_not_hidden() {
    // Verilator refuses to build in a path containing a space: its own
    // `verilated.mk` stops with "Unsupported: GNU Make cannot build in directories
    // containing spaces". A relative `--Mdir .` does not avoid it either, because
    // the check is on the directory. Non-ASCII directory names are fine (covered by
    // the exhaustive frontend test). What ShyHDL must do is report the backend's
    // failure with its output instead of hiding it or reporting a result that does
    // not exist.
    let artifact = compile_testbench(
        REGPIPE_TEST,
        "regpipe.shy",
        "reset_enable_pipeline",
        &regpipe_design(),
    )
    .expect("generate");
    let build_dir = dir("with space/out");
    let options = SimOptions::for_testbench(
        build_dir.clone(),
        &artifact,
        &regpipe_design(),
        vec![SourceFile::new("regpipe_dut.v", REGPIPE_DUT)],
    );
    let report = simulator().run(&options).expect("run");
    match report.outcome {
        Outcome::CompileError => {
            assert!(!report.is_pass());
            let log = std::fs::read_to_string(&report.build_log_path).expect("build log");
            // The backend's own reason must survive into the log we keep.
            assert!(
                log.contains("cannot build in directories containing spaces")
                    || (log.contains("make") && log.contains("exited with")),
                "the build log must carry the backend's own failure: {log}"
            );
            // The manifest records the failure, so a missing recording is never
            // mistaken for a successful one.
            let manifest = load_manifest(&report.manifest_path).expect("load manifest");
            assert_eq!(manifest.outcome, "compile_error");
            assert!(manifest.wave.is_none());
        }
        // If a future backend handles the space, the run just passes.
        Outcome::Pass => {}
        other => panic!("unexpected outcome {other}: {}", report.summary_line()),
    }
}

/// The DUT of the recording-identity test: its next state depends on the
/// backend's random seed, so the same build produces a different waveform.
const RND_DUT: &str = r#"
module Rnd(input clk, input rst_n, output reg [7:0] v);
  always @(posedge clk or negedge rst_n)
    if (!rst_n) v <= 8'd0;
    else v <= $random;
endmodule
"#;

const RND_TEST: &str = r##"
#[hardware_test]
fn random_walk() {
    let mut dut = Rnd::new();
    clock!(dut.clk, period = ns(10), initial = false);
    initial! {
        dut.rst_n = true;
        wait(posedge(dut.clk));
        wait(posedge(dut.clk));
        wait(posedge(dut.clk));
        wait(posedge(dut.clk));
        finish!();
    }
}
"##;

fn rnd_design() -> DesignInfo {
    DesignInfo::new(
        "Rnd",
        "Rnd",
        vec![
            bool_port("clk", PortDirection::In),
            bool_port("rst_n", PortDirection::In),
            ModulePort::new("v", "v", PortDirection::Out, uint(8)),
        ],
    )
}

#[test]
fn a_stale_manifest_is_refused_even_when_the_waveform_path_is_reused() {
    // AC-MVP-034 hardening: the recording is identified by its own content, not
    // by the file name, so a manifest from an earlier run cannot be paired with a
    // later recording that reuses `wave.vcd`.
    let artifact =
        compile_testbench(RND_TEST, "rnd.shy", "random_walk", &rnd_design()).expect("generate");
    let build_dir = dir("recording-identity");
    let simulator = simulator();

    let mut first = SimOptions::for_testbench(
        build_dir.clone(),
        &artifact,
        &rnd_design(),
        vec![SourceFile::new("rnd_dut.v", RND_DUT)],
    );
    first.wave = WaveOption::vcd();
    first.design_build_id = Some("same-build-id".to_string());
    first.seed = Some(1);
    let first_report = simulator.run(&first).expect("first run");
    assert!(first_report.is_pass(), "{}", first_report.summary_line());
    let first_wave = first_report.wave_path.clone().expect("first waveform");
    let saved_manifest = build_dir.join("saved_first_run.manifest.json");
    std::fs::copy(&first_report.manifest_path, &saved_manifest).expect("keep the first manifest");

    // Same build directory, same design, same build id: only the seed (and so the
    // recorded stimulus) differs. The build itself is reused.
    let mut second = first.clone();
    second.seed = Some(2);
    let second_report = simulator.run(&second).expect("second run");
    assert!(second_report.is_pass(), "{}", second_report.summary_line());
    assert_eq!(
        second_report.command_lines.len(),
        1,
        "the second run must reuse the compiled model: {:?}",
        second_report.command_lines
    );

    let first_manifest = load_manifest(&saved_manifest).expect("load the first manifest");
    let second_manifest =
        load_manifest(&second_report.manifest_path).expect("load the second manifest");
    assert_ne!(first_manifest.run_id, second_manifest.run_id);
    // This is what a build-id-and-path check cannot see: the same build id and the
    // same wave path, but a different recording.
    assert_eq!(
        first_manifest.design.build_id,
        second_manifest.design.build_id
    );
    assert_eq!(
        first_manifest.wave.as_ref().unwrap().path,
        second_manifest.wave.as_ref().unwrap().path
    );
    assert_ne!(
        first_manifest.wave.as_ref().unwrap().digest,
        second_manifest.wave.as_ref().unwrap().digest,
        "the two runs must have recorded different content"
    );
    // The current manifest pairs with the file on disk.
    assert_eq!(
        second_manifest
            .verify_wave(&build_dir)
            .expect("current recording verifies"),
        first_wave
    );
    // The stale manifest must be refused, and the reason must be the recording
    // identity rather than a missing file.
    let error = first_manifest
        .verify_wave(&build_dir)
        .unwrap_err()
        .to_string();
    assert!(error.contains("mismatch"), "{error}");
    assert!(
        error.contains(
            first_manifest
                .wave
                .as_ref()
                .unwrap()
                .digest
                .trim_start_matches("fnv1a64-")
        ),
        "{error}"
    );
    assert!(
        error.contains(
            second_manifest
                .wave
                .as_ref()
                .unwrap()
                .digest
                .trim_start_matches("fnv1a64-")
        ),
        "{error}"
    );

    // Replacing the file with different bytes is refused too, and so is losing it.
    std::fs::write(&first_wave, "not a waveform").unwrap();
    assert!(second_manifest.verify_wave(&build_dir).is_err());
    std::fs::remove_file(&first_wave).unwrap();
    assert!(second_manifest.verify_wave(&build_dir).is_err());
}

/// A DUT that exercises two's complement in real Verilog: an adder that wraps at
/// its width, an arithmetic (`>>>`) and a logical (`>>`) shift of the same signed
/// input, and a signed comparison.
const SIGNED_DUT: &str = r#"
module SignedArith(
    input signed [7:0] a,
    input signed [7:0] b,
    output signed [7:0] sum,
    output signed [7:0] shifted,
    output [7:0] logical_shift,
    output is_neg
);
  assign sum = a + b;
  assign shifted = a >>> 1;
  assign logical_shift = a >> 1;
  assign is_neg = a < 0;
endmodule
"#;

const SIGNED_TEST: &str = r##"
#[hardware_test(timeunit = "1ns", precision = "1ps")]
fn signed_semantics() {
    let mut dut = SignedArith::new();
    let mut u: uint<8> = 0xff;
    let mut wide: int<16> = 0;
    initial! {
        dut.a = -8;
        dut.b = 1;
        delay(ps(1));
        assert_eq!(dut.sum, -7);
        assert!(dut.is_neg == true);
        assert!(dut.a < 0);
        assert_eq!(dut.shifted, -4);
        assert_eq!(dut.logical_shift, 124);
        assert_eq!(dut.sum, dut.a + dut.b);
        dut.a = -128;
        dut.b = -1;
        delay(ps(1));
        assert_eq!(dut.sum, 127);
        dut.a = -1;
        delay(ps(1));
        assert_eq!(dut.shifted, -1);
        assert_eq!(u >> 1, 0x7f);
        assert_eq!(u as int<8>, -1);
        dut.a = 127;
        dut.b = 127;
        delay(ps(1));
        // Signed arithmetic wraps at its own width, so the same two 8 bit operands
        // saturate into -2 rather than being extended to 254 by the assignment.
        assert_eq!(dut.sum, -2);
        // A literal is the one thing that takes the target's width, so a wider
        // value is still expressible without any implicit extension of a runtime
        // value (which is refused at generation time, see testbench_gen).
        wide = 254;
        assert_eq!(wide, 254);
        pass!();
        finish!();
    }
}
"##;

const SIGNED_FAIL_TEST: &str = r##"
#[hardware_test(timeunit = "1ns", precision = "1ps")]
fn negative_in_fail_lines() {
    let mut dut = SignedArith::new();
    initial! {
        dut.a = 1;
        dut.b = 2;
        delay(ps(1));
        assert_eq!(dut.sum, -7);
        pass!();
        finish!();
    }
}
"##;

fn signed_design() -> DesignInfo {
    DesignInfo::new(
        "SignedArith",
        "SignedArith",
        vec![
            ModulePort::new("a", "a", PortDirection::In, ValueType::SInt { width: 8 }),
            ModulePort::new("b", "b", PortDirection::In, ValueType::SInt { width: 8 }),
            ModulePort::new(
                "sum",
                "sum",
                PortDirection::Out,
                ValueType::SInt { width: 8 },
            ),
            ModulePort::new(
                "shifted",
                "shifted",
                PortDirection::Out,
                ValueType::SInt { width: 8 },
            ),
            ModulePort::new(
                "logical_shift",
                "logical_shift",
                PortDirection::Out,
                uint(8),
            ),
            bool_port("is_neg", PortDirection::Out),
        ],
    )
}

#[test]
fn signed_values_are_two_complement_on_real_verilator() {
    // Every check below distinguishes two's complement from unsigned arithmetic:
    // `>>>` sign-fills, `>>` does not, `< 0` is meaningful, and the sum wraps at
    // the operand width.
    let artifact = compile_testbench(
        SIGNED_TEST,
        "signed.shy",
        "signed_semantics",
        &signed_design(),
    )
    .expect("generate the signed testbench");
    let build_dir = dir("signed-tb");
    let options = SimOptions::for_testbench(
        build_dir,
        &artifact,
        &signed_design(),
        vec![SourceFile::new("signed_dut.v", SIGNED_DUT)],
    );
    let report = simulator()
        .run(&options)
        .expect("run the signed simulation");
    assert!(
        report.is_pass(),
        "signed semantics differ from two's complement: {}\n{}",
        report.summary_line(),
        report.fail_lines.join("\n")
    );
    assert_eq!(report.markers, 1);
}

#[test]
fn negative_values_are_printed_signed_in_fail_lines() {
    // A deliberately failing equality: the structured FAIL line has to show the
    // negative expected value as a negative number, and a failed assertion must
    // suppress every later PASS (REQ-TEST-008).
    let artifact = compile_testbench(
        SIGNED_FAIL_TEST,
        "signed.shy",
        "negative_in_fail_lines",
        &signed_design(),
    )
    .expect("generate the failing signed testbench");
    let build_dir = dir("signed-fail");
    let options = SimOptions::for_testbench(
        build_dir,
        &artifact,
        &signed_design(),
        vec![SourceFile::new("signed_dut.v", SIGNED_DUT)],
    );
    let report = simulator()
        .run(&options)
        .expect("run the failing signed simulation");
    assert_eq!(report.outcome, Outcome::Fail, "{}", report.summary_line());
    assert_eq!(report.fails, 1, "{}", report.fail_lines.join("\n"));
    assert_eq!(
        report.passes, 0,
        "a failed assertion must not be followed by a PASS"
    );
    let line = report.fail_lines.join("\n");
    assert!(line.contains("check=assert_eq"), "{line}");
    assert!(
        line.contains("expected=-7"),
        "a negative operand must be printed signed: {line}"
    );
    assert!(line.contains("actual=3"), "{line}");
}

/// The DUT of the clock-measurement test: two clock inputs and a counter, so one
/// run can measure both a frequency-derived clock and an explicit asymmetric one.
const CLOCKS_DUT: &str = r#"
module Clocks(input clk, input clk2, input rst_n, output reg [7:0] v);
  always @(posedge clk or negedge rst_n)
    if (!rst_n) v <= 8'd0;
    else v <= v + 8'd1;
endmodule
"#;

const CLOCKS_TEST: &str = r##"
#[hardware_test(timeunit = "1ns", precision = "1ps")]
fn two_clocks() {
    let mut dut = Clocks::new();
    gen_clk(dut.clk, mhz(100));
    clock!(dut.clk2, high = ns(6), low = ns(4));
    initial! {
        dut.rst_n = true;
        wait(posedge(dut.clk));
        wait(posedge(dut.clk));
        wait(posedge(dut.clk));
        finish!();
    }
}
"##;

fn clocks_design() -> DesignInfo {
    DesignInfo::new(
        "Clocks",
        "Clocks",
        vec![
            bool_port("clk", PortDirection::In),
            bool_port("clk2", PortDirection::In),
            bool_port("rst_n", PortDirection::In),
            ModulePort::new("v", "v", PortDirection::Out, uint(8)),
        ],
    )
}

#[test]
fn generated_clock_frequencies_are_measured_in_the_waveform() {
    let artifact = compile_testbench(CLOCKS_TEST, "clocks.shy", "two_clocks", &clocks_design())
        .expect("generate");
    // Two clocks, both identified by their full path in the recording, in
    // declaration order.
    let expected: Vec<(String, String)> = vec![
        ("dut".to_string(), format!("TOP.{}.u_dut.clk", artifact.top)),
        (
            "dut".to_string(),
            format!("TOP.{}.u_dut.clk2", artifact.top),
        ),
    ];
    let collected: Vec<(String, String)> = artifact
        .clocks
        .iter()
        .map(|clock| (clock.var.clone(), clock.signal.clone()))
        .collect();
    assert_eq!(collected, expected);

    let build_dir = dir("clock-measurement");
    let mut options = SimOptions::for_testbench(
        build_dir.clone(),
        &artifact,
        &clocks_design(),
        vec![SourceFile::new("clocks_dut.v", CLOCKS_DUT)],
    );
    options.wave = WaveOption::vcd();
    let report = simulator()
        .run(&options)
        .expect("run the two-clock simulation");
    assert!(report.is_pass(), "{}", report.summary_line());

    // The measurement is taken from the recording itself, not from the generated
    // text: 100 MHz at precision 1ps is a 10000 tick period with equal phases.
    let wave = report.wave_path.clone().expect("waveform");
    let signals = vcd_signals(&wave);
    let clk = signal_id(&signals, &expected[0].1);
    let clk2 = signal_id(&signals, &expected[1].1);
    let clk_edges = vcd_scalar_edges(&wave, clk);
    let clk2_edges = vcd_scalar_edges(&wave, clk2);
    assert_eq!(
        same_value_deltas(&clk_edges, true),
        vec![10_000, 10_000],
        "100 MHz means a 10 ns period between rising edges: {clk_edges:?}"
    );
    // Every completed phase has the expected length; the recording ends inside
    // the last phase, so the number of phases is not asserted.
    assert_every_duration(&clk_edges, true, 5_000, "100 MHz high phase");
    assert_every_duration(&clk_edges, false, 5_000, "100 MHz low phase");
    // The explicit asymmetric clock really is 6 ns high and 4 ns low.
    assert_every_duration(&clk2_edges, true, 6_000, "asymmetric high phase");
    assert_every_duration(&clk2_edges, false, 4_000, "asymmetric low phase");

    // The manifest carries the same clocks, and validation accepts them because
    // each names a recorded instance and a signal directly below its root.
    let manifest = load_manifest(&report.manifest_path).expect("load manifest");
    let manifest_clocks: Vec<(String, String)> = manifest
        .clocks
        .iter()
        .map(|clock| (clock.var.clone(), clock.signal.clone()))
        .collect();
    assert_eq!(manifest_clocks, expected);
}

/// Full dotted path to VCD id, from a VCD header.
fn vcd_signals(path: &Path) -> Vec<(String, String)> {
    let text = std::fs::read_to_string(path).expect("read the waveform");
    let mut stack: Vec<String> = Vec::new();
    let mut signals = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if let Some(rest) = line.strip_prefix("$scope") {
            let name = rest.split_whitespace().nth(1).unwrap_or("?").to_string();
            let full = match stack.last() {
                Some(parent) => format!("{parent}.{name}"),
                None => name,
            };
            stack.push(full);
        } else if line.starts_with("$upscope") {
            stack.pop();
        } else if let Some(rest) = line.strip_prefix("$var") {
            // `$var wire 1 <id> <name> $end`
            let parts: Vec<&str> = rest.split_whitespace().collect();
            if parts.len() >= 4 {
                if let Some(scope) = stack.last() {
                    signals.push((format!("{}.{}", scope, parts[3]), parts[2].to_string()));
                }
            }
        }
    }
    signals
}

fn signal_id(signals: &[(String, String)], path: &str) -> String {
    signals
        .iter()
        .find(|(signal, _)| signal == path)
        .unwrap_or_else(|| panic!("{path} is not in the waveform: {signals:?}"))
        .1
        .clone()
}

/// Scalar value changes of one signal, as `(time, value)` in the file's time scale.
fn vcd_scalar_edges(path: &Path, id: String) -> Vec<(u64, bool)> {
    let text = std::fs::read_to_string(path).expect("read the waveform");
    let mut time = 0u64;
    let mut edges = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if let Some(rest) = line.strip_prefix('#') {
            if let Ok(parsed) = rest.trim().parse::<u64>() {
                time = parsed;
            }
        } else if !line.is_empty() {
            let mut characters = line.chars();
            let value = characters.next().expect("non-empty");
            if value == '0' || value == '1' {
                let signal: String = characters.collect();
                if signal == id {
                    edges.push((time, value == '1'));
                }
            }
        }
    }
    edges
}

/// Distances between consecutive changes to `value`.
fn same_value_deltas(edges: &[(u64, bool)], value: bool) -> Vec<u64> {
    let times: Vec<u64> = edges
        .iter()
        .filter(|(_, level)| *level == value)
        .map(|(time, _)| *time)
        .collect();
    times.windows(2).map(|pair| pair[1] - pair[0]).collect()
}

/// Every completed `value` phase lasts exactly `expected`, and there is at least
/// one of them.
fn assert_every_duration(edges: &[(u64, bool)], value: bool, expected: u64, what: &str) {
    let durations = level_durations(edges, value);
    assert!(
        !durations.is_empty(),
        "{what}: no completed phase in {edges:?}"
    );
    for duration in &durations {
        assert_eq!(*duration, expected, "{what}: {edges:?}");
    }
}

/// How long the signal stays at `value` for each completed phase.
fn level_durations(edges: &[(u64, bool)], value: bool) -> Vec<u64> {
    let mut durations = Vec::new();
    let mut entered = None;
    for (time, level) in edges {
        if *level == value {
            entered = Some(*time);
        } else if let Some(start) = entered.take() {
            durations.push(time - start);
        }
    }
    durations
}

/// The DUT of the array test: array ports of several shapes, packed exactly as
/// the testbench assumes (element 0 in the low bits, struct fields high first).
const ARRAYS_DUT: &str = r#"
module Arrays(
    input [11:0] u4x3,
    input [15:0] i8x2,
    input [7:0] nested,
    input [15:0] word,
    input [31:0] points,
    input [3:0] flags,
    output [11:0] sum
);
  assign sum = u4x3;
endmodule
"#;

const ARRAYS_TEST: &str = r##"
#[hardware_test(timeunit = "1ns", precision = "1ps")]
fn arrays() {
    let mut dut = Arrays::new();
    let mut a: [uint<4>; 3] = [1, 2, 3];
    let mut b: [uint<4>; 3] = [0; 3];
    let mut i: uint<2> = 2;
    let mut sub1: [uint<4>; 1] = [0; 1];
    let mut inner: uint<2> = 1;
    let mut out: uint<2> = 3;
    initial! {
        dut.u4x3 = a;
        dut.i8x2 = [0; 2];
        // An array-shaped value takes a shaped literal: `[0; 2]` here would be a
        // scalar standing in for `[[uint<2>; 2]; 2]`.
        dut.nested = [[0; 2]; 2];
        dut.word.x = 0;
        dut.word.vals = [0; 2];
        dut.points[0].x = 0;
        dut.points[0].vals = [0; 2];
        dut.points[1].x = 0;
        dut.points[1].vals = [0; 2];
        dut.flags = [false; 4];
        delay(ps(1));
        assert_eq!(a[0], 1);
        assert_eq!(a[i], 3);
        // `i` was 2 for the three-element array above; the arrays below hold two
        // elements, so the index comes back into range.
        i = 1;
        b = a;
        assert_eq!(b[2], 3);
        // Writing one element leaves its neighbours untouched.
        b[1] = 9;
        assert_eq!(b[1], 9);
        assert_eq!(b[0], 1);
        assert_eq!(b[2], 3);
        for k in 0..3 {
            b[k] = 7;
        }
        assert_eq!(b[0], 7);
        assert_eq!(b[2], 7);
        // A one element sub-array is still an array.
        sub1 = a.slice(1, 2);
        assert_eq!(sub1[0], 2);
        dut.i8x2[0] = -1;
        assert_eq!(dut.i8x2[0], -1);
        // A dynamic index into a signed element stores and reads back signed.
        dut.i8x2[i] = -1;
        assert_eq!(dut.i8x2[i], -1);
        dut.nested[0][1] = 3;
        assert_eq!(dut.nested[0][1], 3);
        // Successful writes through both dynamic layers ...
        dut.nested[i][inner] = 1;
        assert_eq!(dut.nested[i][inner], 1);
        assert_eq!(dut.nested[0][1], 3);
        // ... and through a dynamic element index plus a static field.
        dut.points[i].x = 0xcdu8;
        assert_eq!(dut.points[i].x, 0xcdu8);
        assert_eq!(dut.points[0].x, 0);
        dut.word.vals[1] = 7;
        assert_eq!(dut.word.vals[1], 7);
        // An out-of-range dynamic write has no effect on any backend; the value it
        // must not disturb is the neighbouring element.
        dut.nested[0][1] = 3;
        dut.nested[0][out] = 1;
        assert_eq!(dut.nested[0][1], 3);
        pass!();
        finish!();
    }
}
"##;

fn array_of(element: ValueType, len: usize) -> ValueType {
    ValueType::Array {
        element: Box::new(element),
        len,
    }
}

fn point_type() -> ValueType {
    ValueType::Struct {
        name: "Point".into(),
        fields: vec![
            shyhdl::metadata::TypeField {
                name: "x".into(),
                ty: uint(8),
            },
            shyhdl::metadata::TypeField {
                name: "vals".into(),
                ty: array_of(uint(4), 2),
            },
        ],
    }
}

fn arrays_design() -> DesignInfo {
    DesignInfo::new(
        "Arrays",
        "Arrays",
        vec![
            ModulePort::new("u4x3", "u4x3", PortDirection::In, array_of(uint(4), 3)),
            ModulePort::new(
                "i8x2",
                "i8x2",
                PortDirection::In,
                array_of(ValueType::SInt { width: 8 }, 2),
            ),
            ModulePort::new(
                "nested",
                "nested",
                PortDirection::In,
                array_of(array_of(uint(2), 2), 2),
            ),
            ModulePort::new("word", "word", PortDirection::In, point_type()),
            ModulePort::new(
                "points",
                "points",
                PortDirection::In,
                array_of(point_type(), 2),
            ),
            ModulePort::new(
                "flags",
                "flags",
                PortDirection::In,
                array_of(ValueType::Bool, 4),
            ),
            ModulePort::new("sum", "sum", PortDirection::Out, uint(12)),
        ],
    )
}

#[test]
fn arrays_work_on_real_verilator() {
    // Legal static and dynamic indices, a `uint<2>` index over three elements,
    // whole copies, sub-arrays, nested arrays, struct-of-array and array-of-struct
    // all have to behave. An out-of-range *read* is deliberately not asserted:
    // Verilator is two-state, so what it substitutes for `x` is a backend detail
    // (REQ-SIM-007) that this test does not pin.
    let artifact =
        compile_testbench(ARRAYS_TEST, "arrays.shy", "arrays", &arrays_design()).expect("generate");
    let build_dir = dir("arrays-tb");
    let options = SimOptions::for_testbench(
        build_dir,
        &artifact,
        &arrays_design(),
        vec![SourceFile::new("arrays_dut.v", ARRAYS_DUT)],
    );
    let report = simulator().run(&options).expect("run the array simulation");
    assert!(
        report.is_pass(),
        "array semantics differ: {}\n{}",
        report.summary_line(),
        report.fail_lines.join("\n")
    );
    assert_eq!(report.markers, 1);
}

/// Dotted scope paths of a VCD file, for example `TOP.tb_reg8.u_dut`.
fn vcd_scopes(path: &Path) -> Vec<String> {
    let text = std::fs::read_to_string(path).expect("read the waveform");
    let mut stack: Vec<String> = Vec::new();
    let mut scopes = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if let Some(rest) = line.strip_prefix("$scope") {
            let name = rest.split_whitespace().nth(1).unwrap_or("?").to_string();
            let parent = stack.last().cloned();
            let full = match parent {
                Some(parent) => format!("{parent}.{name}"),
                None => name,
            };
            scopes.push(full.clone());
            stack.push(full);
        } else if line.starts_with("$upscope") {
            stack.pop();
        }
    }
    scopes
}

/// Process ids whose command line mentions `needle`, used to prove that a killed
/// run left nothing behind.
fn process_ids_matching(needle: &str) -> Vec<u32> {
    let mut found = Vec::new();
    let Ok(entries) = std::fs::read_dir("/proc") else {
        return found;
    };
    for entry in entries.flatten() {
        let Some(pid) = entry
            .file_name()
            .to_str()
            .and_then(|name| name.parse::<u32>().ok())
        else {
            continue;
        };
        if let Ok(cmdline) = std::fs::read(format!("/proc/{pid}/cmdline")) {
            let text = String::from_utf8_lossy(&cmdline);
            if text.contains(needle) && pid != std::process::id() {
                found.push(pid);
            }
        }
    }
    found
}

/// The ShyHDL source of the whole pipeline: a register with an asynchronous
/// reset and an enable, plus a two-stage pipeline in the same module.
const REGPIPE_SHY: &str = r#"
#[hardware_instance]
struct RegPipe {
    #[In] clk: bool,
    #[In] rst_n: bool,
    #[In] enable: bool,
    #[In] rd: uint<8>,
    #[In] pd: uint<8>,
    #[Out] rq: uint<8>,
    #[Out] pq1: uint<8>,
    #[Out] pq2: uint<8>,
}

impl Hardware for RegPipe {
    fn run(&mut self) {
        always! {
            if negedge(self.rst_n) {
                self.rq = 0;
                self.pq1 = 0;
                self.pq2 = 0;
            } else if posedge(self.clk) {
                if self.enable {
                    self.rq = self.rd;
                }
                self.pq1 = self.pd;
                self.pq2 = self.pq1;
            }
        }
    }
}

#[hardware_test]
fn regpipe_from_frontend() {
    let mut dut = RegPipe::new();
    clock!(dut.clk, period = ns(10), initial = false);
    reset!(dut.rst_n, active_low, setup = ns(12), hold = ns(24));
    initial! {
        dut.enable = true;
        dut.rd = 0xffu8;
        dut.pd = 0x00u8;
        wait(posedge(dut.clk));
        delay(ps(1));
        assert_eq!(dut.rq, 0xffu8);
        delay(ns(7));
        assert_eq!(dut.rq, 0x00u8);
        delay(ns(14));
        assert_eq!(dut.rq, 0x00u8);
        assert_eq!(dut.pq1, 0x00u8);
        pass!();
        delay(ns(10));
        dut.enable = true;
        dut.rd = 0x5au8;
        wait(posedge(dut.clk));
        delay(ps(1));
        assert_eq!(dut.rq, 0x5au8);
        pass!();
        dut.enable = false;
        dut.rd = 0x11u8;
        wait(posedge(dut.clk));
        delay(ps(1));
        assert_eq!(dut.rq, 0x5au8);
        pass!();
        dut.pd = 0x01u8;
        wait(posedge(dut.clk));
        delay(ps(1));
        assert_eq!(dut.pq1, 0x01u8);
        assert_eq!(dut.pq2, 0x00u8);
        dut.pd = 0x02u8;
        wait(posedge(dut.clk));
        delay(ps(1));
        assert_eq!(dut.pq1, 0x02u8);
        assert_eq!(dut.pq2, 0x01u8);
        pass!();
        finish!();
    }
}
"#;

/// The adapter the integration layer needs: a few lines that turn the frontend's
/// [`Design`] into the testbench generator's [`DesignInfo`]. It lives in the test
/// so the promise is verified rather than described.
fn design_info_from(design: &shyhdl::frontend::Design) -> DesignInfo {
    let top = design.top();
    DesignInfo::new(
        top.verilog_name.clone(),
        top.source_name.clone(),
        top.ports
            .iter()
            .map(|port| {
                // A clock is an ordinary input: which one the test drives as a
                // clock is decided by `gen_clk`/`clock!`, not by the design.
                let direction = match port.dir {
                    shyhdl::frontend::PortDir::Out => PortDirection::Out,
                    _ => PortDirection::In,
                };
                ModulePort::new(
                    port.source_name.clone(),
                    port.verilog_name.clone(),
                    direction,
                    port.ty.clone(),
                )
            })
            .collect(),
    )
}

#[test]
fn frontend_to_testbench_to_verilator_end_to_end() {
    // The real pipeline: ShyHDL source -> frontend Verilog -> generated
    // testbench -> Verilator. Nothing here is a hand-written DUT fixture.
    let compiled = shyhdl::frontend::compile(REGPIPE_SHY, "regpipe.shy", "RegPipe")
        .unwrap_or_else(|diagnostic| panic!("frontend failed: {diagnostic}"));
    let design = design_info_from(&compiled.design);
    assert_eq!(design.top, "RegPipe");
    assert!(
        compiled.verilog.contains("module RegPipe"),
        "{}",
        compiled.verilog
    );

    let artifact = compile_testbench(REGPIPE_SHY, "regpipe.shy", "regpipe_from_frontend", &design)
        .expect("generate the testbench from frontend output");

    let build_dir = dir("frontend-e2e");
    let mut options = SimOptions::for_testbench(
        build_dir.clone(),
        &artifact,
        &design,
        vec![SourceFile::new(
            "regpipe_design.v",
            compiled.verilog.clone(),
        )],
    );
    options.design_build_id = Some(compiled.metadata.build_id.clone());
    options.wave = WaveOption::vcd();
    let report = simulator().run(&options).expect("run the simulation");

    assert!(
        report.is_pass(),
        "frontend end-to-end run did not pass: {}\nstdout:\n{}\nstderr:\n{}",
        report.summary_line(),
        report.stdout,
        report.stderr
    );
    assert_eq!(report.markers, 4, "all four cases must complete");

    // The recording is paired with the frontend's own build id, and its scopes
    // resolve.
    let manifest = load_manifest(&report.manifest_path).expect("load manifest");
    assert_eq!(
        manifest.design.build_id,
        Some(compiled.metadata.build_id.clone())
    );
    assert_eq!(manifest.roots[0].wave_root, artifact.instances[0].scope);
    assert_eq!(manifest.roots[0].source_root, "RegPipe");
    assert_eq!(manifest.test.top_type, artifact.top_type);
    let scopes = vcd_scopes(&report.wave_path.clone().expect("waveform"));
    assert!(scopes.contains(&artifact.instances[0].scope), "{scopes:?}");
}

/// The exhaustive adder, written in ShyHDL and compiled by the frontend, wired
/// next to an independent reference by a hand-written comparison harness.
const ADDER_SHY: &str = r#"
#[hardware_instance]
struct Adder8 {
    #[In] a: uint<8>,
    #[In] b: uint<8>,
    #[Out] c: uint<8>,
    #[Out] cin: bool,
}

impl Hardware for Adder8 {
    fn run(&mut self) {
        let wide: uint<9> = self.a.zext::<9>() + self.b.zext::<9>();
        self.c = wide[0..8];
        self.cin = wide.get(8);
    }
}

#[hardware_test]
fn adder8_frontend_exhaustive() {
    let mut dut = AdderCompare::new();
    let mut count: uint<17> = 0;
    initial! {
        dut.a = 0x00u8;
        dut.b = 0x00u8;
        delay(ps(1));
        assert!(dut.mismatch == false);
        for i in 0..256 {
            for j in 0..256 {
                dut.a = i[0..8];
                dut.b = j[0..8];
                delay(ps(1));
                count = count + 1;
                if (dut.mismatch == true) {
                    assert!(dut.mismatch == false);
                }
            }
        }
        assert_eq!(count, 0x10000);
        pass!();
        finish!();
    }
}
"#;

/// Wraps the frontend-generated `Adder8` and the hand-written `RefAdder8` so one
/// testbench can compare them on every input pair.
const ADDER_HARNESS: &str = r#"
module RefAdder8(input [7:0] a, input [7:0] b, output [7:0] c, output cout);
  assign {cout, c} = a + b;
endmodule

module AdderCompare(input [7:0] a, input [7:0] b, output mismatch, output [7:0] sum, output carry);
  wire [7:0] dut_c;
  wire [7:0] ref_c;
  wire dut_cout;
  wire ref_cout;
  Adder8 u_dut(.a(a), .b(b), .c(dut_c), .cin(dut_cout));
  RefAdder8 u_ref(.a(a), .b(b), .c(ref_c), .cout(ref_cout));
  assign mismatch = (dut_c !== ref_c) || (dut_cout !== ref_cout);
  assign sum = dut_c;
  assign carry = dut_cout;
endmodule
"#;

#[test]
fn frontend_adder_is_exhaustively_correct() {
    let compiled = shyhdl::frontend::compile(ADDER_SHY, "adder8.shy", "Adder8")
        .unwrap_or_else(|diagnostic| panic!("frontend failed: {diagnostic}"));
    assert!(
        compiled.verilog.contains("module Adder8"),
        "{}",
        compiled.verilog
    );

    let harness = DesignInfo::new(
        "AdderCompare",
        "AdderCompare",
        vec![
            ModulePort::new("a", "a", PortDirection::In, uint(8)),
            ModulePort::new("b", "b", PortDirection::In, uint(8)),
            ModulePort::new("mismatch", "mismatch", PortDirection::Out, ValueType::Bool),
            ModulePort::new("sum", "sum", PortDirection::Out, uint(8)),
            ModulePort::new("carry", "carry", PortDirection::Out, ValueType::Bool),
        ],
    );
    let artifact = compile_testbench(
        ADDER_SHY,
        "adder8.shy",
        "adder8_frontend_exhaustive",
        &harness,
    )
    .expect("generate the exhaustive testbench");

    let build_dir = relative_dir("前端穷举/sim");
    let mut options = SimOptions::for_testbench(
        build_dir,
        &artifact,
        &harness,
        vec![
            SourceFile::new("adder8_design.v", compiled.verilog.clone()),
            SourceFile::new("adder_harness.v", ADDER_HARNESS),
        ],
    );
    options.design_build_id = Some(compiled.metadata.build_id.clone());
    let report = simulator()
        .run(&options)
        .expect("run the exhaustive simulation");
    assert!(
        report.is_pass(),
        "the frontend adder is not exhaustively correct: {}\n{}",
        report.summary_line(),
        report.fail_lines.join("\n")
    );
    assert_eq!(report.fails, 0);
    assert_eq!(report.markers, 1);
}
